args:
& {
    $taskNames = @('Borealis Agent','Borealis Agent (UserHelper)');
    foreach ($name in $taskNames) {
        $taskExists = $false;
        try { Get-ScheduledTask -TaskName $name -ErrorAction Stop | Out-Null; $taskExists = $true } catch {
            try { schtasks.exe /Query /TN $name 2>$null | Out-Null; if ($LASTEXITCODE -eq 0) { $taskExists = $true } } catch {}
        };
        if (-not $taskExists) { continue };
        Write-Host ('Stopping scheduled task: {0}' -f $name);
        try { Stop-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue } catch {}
        try { schtasks.exe /End /TN $name /F 2>$null | Out-Null } catch {}
        try {
            for ($i = 0; $i -lt 20; $i++) {
                $info = Get-ScheduledTaskInfo -TaskName $name -ErrorAction Stop;
                if ($info.State -ne 'Running' -and $info.State -ne 'Queued') { break }
                Start-Sleep -Milliseconds 500
            }
        } catch {}
    };
    foreach ($procName in @('python','pythonw')) {
        try { $procs = Get-Process -Name $procName -ErrorAction Stop } catch { continue };
        foreach ($proc in $procs) {
            Write-Host ('Terminating process: {0} (PID {1})' -f $proc.ProcessName, $proc.Id);
            try { if (-not $proc.HasExited) { $null = $proc.CloseMainWindow(); Start-Sleep -Milliseconds 500 } } catch {}
            try { if (-not $proc.HasExited) { $proc.Kill(); $proc.WaitForExit(2000) | Out-Null } } catch {}
            if (-not $proc.HasExited) {
                $taskkillOutput = taskkill.exe /PID $($proc.Id) /F 2>&1;
                if ($LASTEXITCODE -ne 0 -and $taskkillOutput) {
                    Write-Host ('taskkill.exe returned exit code {0} for PID {1}: {2}' -f $LASTEXITCODE, $proc.Id, $taskkillOutput)
                }
            }
        }
    }
}

& {
    $taskNames = @('Borealis Agent','Borealis Agent (UserHelper)');
    foreach ($name in $taskNames) {
        Write-Host ('Starting scheduled task: {0}' -f $name);
        $started = $false;
        try {
            Start-ScheduledTask -TaskName $name -ErrorAction Stop | Out-Null
            $started = $true
        } catch {}
        if (-not $started) {
            try { schtasks.exe /Run /TN $name 2>$null | Out-Null; $started = $true } catch {}
        }
        if (-not $started) {
            Write-Host ('Unable to start scheduled task: {0}' -f $name) -ForegroundColor DarkYellow
        }
    }
}
